from lib import *
S = SS('x86')
steps = [
    step("一个 HTTP 请求同时产生指标和链路。装了 actuator 和 micrometer-tracing-bridge-brave 之后(采样率设成 1.0),GET /work 返回 traceId=6ad6de2363b09c4c3a40e9769a75e650;Boot 默认的日志格式里自动多了关联 id,形如 [demo] [nio-9602-exec-2] [6ad6de2363b09c4c3a40e9769a75e650-3a40e9769a75e650],前半是 traceId、后半是 spanId。我自己的 SpanHandler 收集到 2 个 span:一个是服务端 span「http get /work」,标签有 exception=none、http.url=/work、method=GET、outcome=SUCCESS、status=200、uri=/work,没有父 span;另一个是它的子 span「svc-call」,标签 class=demo.Svc、layer=service、method=call。同一个请求在指标侧是 http.server.requests(uri=/work),COUNT 1,标签 exception、method、error、outcome、status。一次观察,指标和链路各一份。", t=tl(S(1)), mark=lidx(S(1), '日志行', 'http get /work', 'svc-call'), done=lidx(S(1), 'GET /work →', '指标 http.server.requests'), b=bars([['收集到的 span 个数', 2, '2'], ['http.server.requests?uri=/work 的 COUNT', 1, '1'], ['指标标签个数(exception、method、error、outcome、status)', 5, '5'], ['服务端 span 的标签个数', 6, '6']], 6, done=[0, 1], mark=[2, 3]), kv=KV([['日志', '默认格式里自动带 [traceId-spanId]'], ['服务端 span', 'http get /work,没有父 span'], ['子 span', 'svc-call,有父 span'], ['指标', 'http.server.requests,同一次请求']], ['日志'])),
    step("手动创建 Observation:Observation.createNotStarted(\"order.process\", registry).lowCardinalityKeyValue(\"type\", type).highCardinalityKeyValue(\"orderId\", …).observe(…)。调用 3 次(type 分别是 a、a、b,orderId 每次都不同)。指标侧 order.process:COUNT 3,标签只有 type(取值 a、b)和 error(none),orderId 没有出现在指标标签里。链路侧 3 个 span,标签是 {orderId=30bb2f59, type=a}、{orderId=607e3226, type=a}、{orderId=bc3483bd, type=b},每个 span 都带着 orderId,并且都有父 span(它们是各自 HTTP 请求的子 span)。低基数标签(取值有限)同时进指标和 span,高基数标签(每次不同)只进 span——这样指标不会因为 orderId 爆炸,排查具体订单时又能在链路里按 orderId 找。", t=tl(S(2)), mark=lidx(S(2), '指标 order.process', 'orderId'), done=lidx(S(2), 'span 个数 3'), b=bars([['order.process 的指标 COUNT', 3, '3'], ['指标标签 type 的取值个数', 2, '2(a、b)'], ['span 个数', 3, '3'], ['span 里不同的 orderId 取值个数', 3, '3'], ['指标标签里 orderId 的取值个数', 0, '0']], 3, done=[0, 2], mark=[3, 4], cur=[1]), kv=KV([['lowCardinalityKeyValue', '进指标标签,也进 span'], ['highCardinalityKeyValue', '只进 span,不进指标标签'], ['orderId', '3 个不同取值,只出现在 span 里'], ['作用', '指标不爆炸,链路又能查到具体订单']], ['highCardinalityKeyValue'])),
    step("@Observed 注解。Service 的方法上标 @Observed(name = \"svc.call\", contextualName = \"svc-call\", lowCardinalityKeyValues = {\"layer\", \"service\"}),再注册一个 ObservedAspect Bean(并有 aspectj starter):调两次 /work。指标侧 svc.call:COUNT 2,标签 method=call、error=none、class=demo.Svc、layer=service;链路侧 span 名字是 contextualName「svc-call」,2 个,标签 class=demo.Svc、layer=service、method=call。本次全部 span 名字是 http get /actuator/metrics/{requiredMetricName}、http get /spans、http get /work、svc-call——连 actuator 自己的 HTTP 请求都被观察了。一个注解同时得到一个 Timer 指标和一个 span,不用分别写指标代码和链路代码。", t=tl(S(3)), mark=lidx(S(3), '指标 svc.call', 'span svc-call'), done=lidx(S(3), '全部 span 名字'), b=bars([['svc.call 的指标 COUNT', 2, '2'], ['svc-call 的 span 个数', 2, '2'], ['svc.call 的指标标签个数', 4, '4'], ['本次出现的 span 名字个数', 4, '4']], 4, done=[0, 1], mark=[2, 3]), kv=KV([['@Observed', '一个注解 = 一个 Timer 指标 + 一个 span'], ['要求', '注册 ObservedAspect Bean,并有 AOP'], ['指标名 / span 名', 'name = svc.call / contextualName = svc-call'], ['标签', 'class、method、error 加自己写的 layer']], ['@Observed'])),
    step("采样与开关(各发 100 个 /plain 请求)。不设 management.tracing.sampling.probability(默认):收集到 /plain 的 span 10 个;probability=1.0:100 个;probability=0.0:0 个。三种情况下指标 http.server.requests?uri=/plain 的 COUNT 都是 100——采样只影响链路,不影响指标。再看开关:management.observations.enable.svc.call=false(采样率 1.0)之后调 5 次 /work:svc.call 指标没有了,svc-call 的 span 是 0 个,而「http get /work」的 span 仍然是 5 个——按观察名字关闭,指标和 span 一起消失,其他观察不受影响。", t=tl(S(4)), mark=lidx(S(4), '不设(默认)', 'enable.svc.call=false'), done=lidx(S(4), 'probability=1.0:', 'probability=0.0'), b=bars([['默认采样率:100 个请求里的 span 个数', 10, '10'], ['probability=1.0:span 个数', 100, '100'], ['probability=0.0:span 个数', 0, '0'], ['三种情况下指标 COUNT', 100, '100']], 100, mark=[0], done=[1, 3], cur=[2]), kv=KV([['默认采样', '100 个请求只留 10 个 span'], ['采样只管链路', '指标 COUNT 仍然是 100'], ['按名字关闭', 'enable.svc.call=false 后指标与 span 一起消失'], ['其他观察', '不受影响(/work 的 span 仍是 5 个)']], ['采样只管链路'])),
]
